<script setup>import{computed,onMounted,provide,ref}from'vue';import{useRoute,useRouter}from'vue-router';import api from '../../../services/api';import{usePlanAdmin}from'../../../composables/usePlanAdmin';import FormErrors from '../../../components/ui/FormErrors.vue';import PlanStatusBadge from '../../../components/admin/plans/PlanStatusBadge.vue';const route=useRoute(),router=useRouter(),s=usePlanAdmin(),actionError=ref(null),deleting=ref(false),menu=ref(false);provide('planAdmin',s);onMounted(()=>s.load(route.params.id));const tabs=[['admin.plans.show','Overview'],['admin.plans.limits','Limits'],['admin.plans.features','Features'],['admin.plans.subscriptions','Subscriptions'],['admin.plans.activity','Activity']];const money=computed(()=>s.plan.value?new Intl.NumberFormat(undefined,{style:'currency',currency:s.plan.value.currency,maximumFractionDigits:2}).format(Number(s.plan.value.price)):null);const limit=v=>v===null?'Unlimited':Number(v).toLocaleString();async function remove(){menu.value=false;if(!window.confirm(`Delete ${s.plan.value.name}? This action cannot be undone.`))return;deleting.value=true;actionError.value=null;try{await api.delete('/v1/platform/plans/'+s.plan.value.id);await router.replace({name:'admin.plans',query:{deleted:1}})}catch(e){actionError.value=e}finally{deleting.value=false}}async function toggleStatus(){menu.value=false;actionError.value=null;try{const response=await api.put('/v1/platform/plans/'+s.plan.value.id,{...s.plan.value,status:s.plan.value.status==='active'?'inactive':'active'});s.plan.value=response.data.data}catch(e){actionError.value=e}}</script>
<template><div><p v-if="s.loading.value" class="loading-state">Loading plan...</p><FormErrors v-else-if="s.error.value" :error="s.error.value"/><template v-else-if="s.plan.value"><header class="page-header"><div><RouterLink class="back-link" :to="{name:'admin.plans'}">Back to Subscription Plans</RouterLink><div class="mt-3 flex flex-wrap items-center gap-3"><h1>{{s.plan.value.name}}</h1><PlanStatusBadge :status="s.plan.value.status"/></div><p class="text-lg font-semibold text-slate-700">{{money}}<span v-if="Number(s.plan.value.price)"> / {{s.plan.value.billing_period}}</span></p></div><div class="relative flex gap-3"><RouterLink class="btn" :to="{name:'admin.plans.edit',params:{id:route.params.id}}">Edit Plan</RouterLink><button class="btn-secondary" :aria-expanded="menu" @click="menu=!menu">More &#9662;</button><div v-if="menu" class="action-menu top-full"><button @click="toggleStatus">{{s.plan.value.status==='active'?'Deactivate Plan':'Activate Plan'}}</button><button class="danger-item" :disabled="deleting" @click="remove">{{deleting?'Deleting...':'Delete Plan'}}</button></div></div></header><p v-if="route.query.created||route.query.updated" role="status" class="mb-5 rounded-xl bg-emerald-50 p-4 text-emerald-800">{{route.query.created?'Subscription plan created successfully.':'Subscription plan updated successfully.'}}</p><FormErrors :error="actionError"/><div class="grid gap-4 sm:grid-cols-2 xl:grid-cols-5"><article class="summary-card"><p>Active Subscriptions</p><strong>{{s.plan.value.active_subscriptions_count}}</strong></article><article class="summary-card"><p>Trial Subscriptions</p><strong>{{s.plan.value.trial_subscriptions_count}}</strong></article><article class="summary-card"><p>Branch Limit</p><strong>{{limit(s.plan.value.branch_limit)}}</strong></article><article class="summary-card"><p>Member Limit</p><strong>{{limit(s.plan.value.member_limit)}}</strong></article><article class="summary-card"><p>Patient Limit</p><strong>{{limit(s.plan.value.patient_limit)}}</strong></article></div><nav class="clinic-tabs mt-6" aria-label="Plan management"><RouterLink v-for="[name,label] in tabs" :key="name" :to="{name,params:{id:route.params.id}}">{{label}}</RouterLink></nav><RouterView/></template></div></template>
